/**
 * @file ast.hpp
 * @brief Defines the AST nodes generated by the parser.
 *
 * AST node types are represented by the ExpressionVariant std::variant.
 * Expression provides a visit() method that wraps std::visit, allowing
 * callers to visit the underlying node while keeping the variant private.
 *
 * Walking the AST:
 * - Parser::parse() returns an Expression representing the root of the parsed
 * expression. Define a visitor and invoke it with expr.visit(visitor).
 */

#ifndef DEXPR_AST_HPP
#define DEXPR_AST_HPP

#include <concepts>
#include <dexpr/tokens.hpp>
#include <memory>
#include <string>
#include <utility>
#include <variant>
#include <vector>

namespace dexpr::ast {
struct Expression;

// Do not allow nodes to have multiple owners.
using ExprPtr = std::unique_ptr<const Expression>;

struct Identifier {
  std::string value;
};

struct UnaryExpression {
  TokenTypes op;
  ExprPtr right;
};

struct BinaryExpression {
  ExprPtr left;
  TokenTypes op;
  ExprPtr right;
};

struct FuncExpression {
  ExprPtr function;
  std::vector<ExprPtr> args;
};

struct ArrayExpression {
  std::vector<ExprPtr> elements;
};

struct StringLiteral {
  std::string value;
};

// Literals are stored at full precision regardless of how the consumer will
// eventually use them. Narrowing here would lose information before the
// expression ever meets a field: 273.15 is 273.14999389648438 as a float, and
// a legal threshold like 1e40 would not survive at all.
struct FloatLiteral {
  double value;
};

struct IntegerLiteral {
  int value;
};

using ExpressionVariant =
    std::variant<Identifier, UnaryExpression, BinaryExpression, FuncExpression,
                 ArrayExpression, StringLiteral, FloatLiteral, IntegerLiteral>;

template <typename T>
concept ExpressionNode = std::constructible_from<ExpressionVariant, T&&>;

struct Expression {
  template <ExpressionNode T>
  explicit Expression(T&& value) : node_(std::forward<T>(value)) {}

  // This member function will be used for visitors so that
  // the node variant can remain private
  // NOTE: decltype(auto) allows visitors to return references
  template <typename Visitor> decltype(auto) visit(Visitor&& visitor) const {
    return std::visit(std::forward<Visitor>(visitor), node_);
  }

private:
  ExpressionVariant node_;
};

template <ExpressionNode Node, typename... Args>
  requires std::constructible_from<Node, Args&&...>
ExprPtr make_expression(Args&&... args) {
  return std::make_unique<const Expression>(Node{std::forward<Args>(args)...});
}

// Functions
std::string to_string(const Expression& expr);

} // namespace dexpr::ast

#endif
